// Anim name for a skill action row played with weapon MotionType, per
// gender; "" when the row is unknown or has no motion for that type.
static const TCHAR* RoseSkillActionAnim(int32 MotionType, int32 ActionRow, bool bFemale)
{
	if (MotionType < 0 || MotionType >= 20) MotionType = 0;
	int32 Lo = 0, Hi = 150 - 1;
	while (Lo <= Hi)
	{
		const int32 Mid = (Lo + Hi) / 2;
		const int32 R = RoseSkillActionRows[Mid];
		if (R == ActionRow)
			return (bFemale ? RoseSkillMotionF : RoseSkillMotionM)[Mid][MotionType];
		if (R < ActionRow) Lo = Mid + 1; else Hi = Mid - 1;
	}
	return TEXT("");
}
